-- =============================================================
-- Migration 002: Create qr_payment_requests table
-- =============================================================
-- Stores QR payment requests generated by the backend.
-- Each QR encodes an EIP-681 URI (Ethereum payment request)
-- that can be scanned by MetaMask or compatible wallets.
--
-- Lifecycle:
--   1. Backend generates QR → status = PENDING
--   2. User scans QR, sends ETH → status = COMPLETED
--   3. If QR expires (default 15 min) → status = EXPIRED
--   4. If user cancels → status = CANCELLED
--
-- Run: mysql -u root -p sakila < database/migrations/002_create_qr_payment_requests.sql
-- =============================================================

USE sakila;

-- Drop if exists (for idempotent migrations)
DROP TABLE IF EXISTS qr_payment_requests;

CREATE TABLE qr_payment_requests (
    -- Primary key
    id INT AUTO_INCREMENT PRIMARY KEY,

    -- Reference to Sakila payment (nullable: QR created before payment exists)
    payment_id SMALLINT UNSIGNED DEFAULT NULL,

    -- The recipient wallet address (store/contract address)
    recipient_address VARCHAR(42) NOT NULL,

    -- Requested payment amount in ETH
    amount_eth DECIMAL(18, 8) NOT NULL,

    -- Human-readable reference (e.g., "Rental #1234 - Customer John")
    reference VARCHAR(255) NOT NULL,

    -- The full EIP-681 URI encoded in the QR
    eip681_uri TEXT NOT NULL,

    -- Base64-encoded QR image (PNG format)
    qr_image_base64 LONGTEXT NOT NULL,

    -- QR request status
    status ENUM('PENDING', 'COMPLETED', 'EXPIRED', 'CANCELLED') DEFAULT 'PENDING',

    -- Transaction hash once payment is detected
    tx_hash VARCHAR(66) DEFAULT NULL,

    -- Expiration timestamp
    expires_at TIMESTAMP NOT NULL,

    -- Timestamps
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_qr_payment
        FOREIGN KEY (payment_id) REFERENCES payment(payment_id)
        ON DELETE SET NULL
        ON UPDATE CASCADE,

    -- Indexes
    INDEX idx_qr_status (status),
    INDEX idx_qr_expires (expires_at)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='QR payment requests for EIP-681 Ethereum payment URIs';
